_COMPONENT_CSS = r"""*{box-sizing:border-box} :root{--bg:#01050d;--surface:#04111f;--surface2:#020a14;--line:rgba(78,193,244,.25);--line2:rgba(87,215,255,.10);--text:#f2f7ff;--muted:rgba(205,224,241,.68);--cyan:#5deaff;--blue:#2d7cff;--green:#62f5b2;--amber:#ffc968;--red:#ff6572}
.jarvis{position:relative;width:100%;min-height:100dvh;padding:10px 12px 9px;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto auto;gap:9px;overflow:hidden;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-variant-numeric:tabular-nums;background:radial-gradient(circle at 50% 32%,rgba(29,127,229,.105),transparent 34%),radial-gradient(circle at 84% 12%,rgba(50,222,255,.045),transparent 27%),linear-gradient(180deg,#020914 0%,#01050d 72%,#01040a 100%);border:1px solid rgba(67,183,236,.22);border-radius:20px;isolation:isolate}
.jarvis:before{content:"";position:absolute;inset:0;z-index:-3;pointer-events:none;background:linear-gradient(rgba(83,205,255,.020) 1px,transparent 1px),linear-gradient(90deg,rgba(83,205,255,.014) 1px,transparent 1px);background-size:52px 52px;mask-image:linear-gradient(to bottom,transparent,#000 10%,#000 91%,transparent)}
.jarvis:after{content:"";position:absolute;inset:0;z-index:40;pointer-events:none;opacity:.055;background:repeating-linear-gradient(to bottom,rgba(255,255,255,.014) 0 1px,transparent 2px 8px)}
.ambient-grid{position:absolute;inset:0;z-index:-2;pointer-events:none;background:radial-gradient(circle at 10% 18%,rgba(60,190,255,.055),transparent 18%),radial-gradient(circle at 90% 34%,rgba(60,190,255,.035),transparent 20%)} .particles{position:absolute;inset:0;width:100%;height:100%;z-index:-1;opacity:.40;pointer-events:none}
.topbar{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(460px,.82fr);align-items:center;gap:18px;padding:12px 16px;border:1px solid var(--line2);border-radius:15px;background:linear-gradient(180deg,rgba(4,16,31,.78),rgba(2,9,19,.68));box-shadow:inset 0 1px 0 rgba(255,255,255,.025)}
.brand-block{display:flex;align-items:center;gap:14px;min-width:0}.brand-emblem{width:64px;aspect-ratio:1;flex:0 0 auto;display:grid;place-items:center;border:1px solid rgba(100,224,255,.22);border-radius:13px;background:radial-gradient(circle at 50% 35%,rgba(84,218,255,.12),transparent 56%),linear-gradient(180deg,rgba(8,27,48,.95),rgba(2,11,22,.9));box-shadow:inset 0 0 24px rgba(64,194,255,.04)}.brand-emblem svg{width:70%;filter:drop-shadow(0 0 10px rgba(78,221,255,.42))}.brand-kicker{margin-bottom:4px;color:var(--cyan);font-size:12px;font-weight:950;letter-spacing:.24em}.brand-copy h1{margin:0;font-size:clamp(24px,1.65vw,34px);line-height:1;font-weight:950;letter-spacing:.01em;white-space:nowrap}.brand-sub{margin-top:7px;color:var(--muted);font-size:11px;font-weight:750}.brand-sub i{font-style:normal;color:#3eaaff;margin:0 7px}
.system-block{display:grid;grid-template-columns:180px 1fr;gap:16px;align-items:center}.clock-block{padding-right:16px;border-right:1px solid rgba(91,212,255,.13)}.clock-date{font-size:9px;color:var(--muted);font-weight:800}.clock-time{margin-top:2px;font-size:21px;font-weight:950;letter-spacing:.03em}.clock-time small{margin-left:5px;font-size:9px;color:var(--muted)}.clock-session{margin-top:5px;color:var(--green);font-size:8px;font-weight:950;letter-spacing:.16em;text-transform:uppercase}.system-status{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.status-item{display:flex;align-items:flex-start;gap:7px;min-width:0}.status-light{width:8px;height:8px;margin-top:2px;border-radius:50%;background:currentColor;box-shadow:0 0 11px currentColor;flex:0 0 auto}.status-light.healthy{color:var(--green)}.status-light.online{color:#3f87ff}.status-item b{display:block;font-size:8px;letter-spacing:.08em;white-space:nowrap}.status-item small{display:block;margin-top:3px;color:var(--muted);font-size:7px;font-weight:800;white-space:nowrap}
.market-tape{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));min-height:39px;border:1px solid var(--line2);border-radius:11px;overflow:hidden;background:rgba(2,11,22,.72)}.tape-cell{min-width:0;display:flex;align-items:center;justify-content:center;gap:7px;padding:7px 8px;border-right:1px solid rgba(83,205,255,.07);white-space:nowrap;overflow:hidden}.tape-cell:last-child{border-right:0}.tape-cell span,.tape-cell strong{font-size:9px;font-weight:850}.tape-cell .sym{font-size:8px;font-weight:950;letter-spacing:.10em}.tape-cell>span:not(.sym):not(.tiny-wave){color:var(--muted)}.tape-cell .pos{color:var(--green);font-size:13px}.tape-cell .neg{color:var(--red);font-size:13px}.tiny-wave{color:var(--cyan);letter-spacing:-2px}
.hero-grid{min-width:0;min-height:0;display:grid;grid-template-columns:minmax(310px,.83fr) minmax(600px,1.28fr) minmax(310px,.83fr);gap:13px;align-items:start}.intel-stack{min-width:0;display:grid;grid-template-rows:auto auto;gap:14px;align-content:start}.intel-card{position:relative;min-width:0;overflow:hidden;padding:15px 18px 13px 21px;border:1px solid var(--line);border-radius:16px;background:radial-gradient(circle at 8% 0%,rgba(86,228,255,.045),transparent 30%),linear-gradient(180deg,rgba(6,21,39,.90),rgba(2,10,20,.82));box-shadow:inset 0 1px 0 rgba(255,255,255,.026),0 10px 24px rgba(0,0,0,.13)}.card-accent{position:absolute;left:0;top:17px;width:3px;height:25px;border-radius:0 4px 4px 0;background:linear-gradient(#9bfcff,#1a8cff);box-shadow:0 0 10px rgba(91,226,255,.55)}.card-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.card-head h2{margin:0;color:var(--cyan);font-size:13px;font-weight:950;letter-spacing:.17em}.card-head>span{color:#4dafff;font-size:8px;font-weight:950;letter-spacing:.15em}.regime-line{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px}.regime-line>strong{color:var(--green);font-size:18px;font-weight:950;letter-spacing:.03em}.donut{position:relative;width:30px;height:30px;border-radius:50%;background:conic-gradient(#3b8fff 0 62%,rgba(60,122,202,.16) 62% 100%);display:grid;place-items:center;box-shadow:0 0 11px rgba(55,142,255,.12)}.donut:before{content:"";width:21px;height:21px;border-radius:50%;background:#071425;position:absolute}.donut span{position:relative;z-index:1;font-size:6px;font-weight:950;color:#cfeaff}.metric-rows{display:grid;gap:8px;margin-top:10px}.metric-rows.spacious{gap:10px;margin-top:15px}.metric-rows>div{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.metric-rows span{color:rgba(216,231,245,.82);font-size:11px;font-weight:680}.metric-rows b{color:white;font-size:11px;font-weight:950;white-space:nowrap}.metric-rows b.good,.good{color:var(--green)}.metric-rows b.info{color:#42a8ff}.metric-rows b.bad{color:var(--red)}.metric-rows b.warn,.warn{color:var(--amber)}.meter{height:5px;margin-top:12px;border-radius:99px;background:rgba(134,179,240,.14);overflow:hidden}.meter>span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#236fff,#50dfff);box-shadow:0 0 14px rgba(80,223,255,.30)}.card-foot{margin-top:14px;padding-top:10px;border-top:1px solid rgba(83,205,255,.07);display:flex;justify-content:space-between;gap:10px;color:rgba(203,222,240,.61);font-size:9px;font-weight:770}.mini-status{display:inline-flex;align-items:center;gap:6px}.mini-status i{width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 8px currentColor}.mini-status.delayed{color:var(--amber)}
.execution-layout{position:relative}.execution-layout .metric-rows{padding-right:95px}.micro-spark{position:absolute;right:0;top:18px;width:82px;height:62px;filter:drop-shadow(0 0 7px rgba(61,158,255,.12))}

/* V7.2 — restored institutional card styling. Reactor/core rules below are intentionally untouched. */
.intel-card{padding:17px 20px 15px 24px;border-color:rgba(72,203,255,.30);border-radius:18px;background:radial-gradient(circle at 9% 0%,rgba(83,224,255,.065),transparent 32%),linear-gradient(180deg,rgba(6,22,41,.94),rgba(2,10,20,.88));box-shadow:inset 0 1px 0 rgba(255,255,255,.035),inset 0 0 25px rgba(55,175,255,.025),0 12px 28px rgba(0,0,0,.16)}
.card-accent{top:21px;height:28px;width:4px;background:linear-gradient(180deg,#a9ffff 0%,#53e6ff 48%,#1b83ff 100%);box-shadow:0 0 13px rgba(91,226,255,.72)}
.card-head h2{font-size:14px;letter-spacing:.18em;color:#61eaff;text-shadow:0 0 10px rgba(74,219,255,.08)}
.card-head>span{font-size:9px;color:#48aaff;letter-spacing:.16em}
.regime-title{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-top:14px}.regime-title strong{color:var(--green);font-size:22px;font-weight:950;letter-spacing:.01em}.regime-title small{color:rgba(211,228,244,.64);font-size:9px;font-weight:900;letter-spacing:.04em}
.metric-rows{gap:9px;margin-top:12px}.metric-rows.compact-rows{gap:9px;margin-top:14px}.metric-rows span{font-size:12px;font-weight:700;color:rgba(218,233,247,.84)}.metric-rows b{font-size:12px}.metric-rows b.good{color:#62f5b2}.metric-rows b.info{color:#3faaff}.metric-rows b.bad{color:#ff6572}.metric-rows b.warn{color:#ffc968}
.meter{height:7px;margin-top:14px;background:rgba(124,166,216,.16)}.meter>span{background:linear-gradient(90deg,#3276ff 0%,#55dcff 58%,#67f2ff 100%);box-shadow:0 0 17px rgba(80,223,255,.32)}
.regime-probabilities{height:68px;margin-top:14px;display:grid;grid-template-columns:repeat(5,1fr);gap:8px;align-items:end;padding:8px 10px 2px;border:1px solid rgba(82,205,255,.08);border-radius:13px;background:linear-gradient(180deg,rgba(5,24,43,.46),rgba(3,13,25,.38))}.regime-probabilities>div{height:100%;display:grid;grid-template-rows:1fr auto;align-items:end;gap:4px}.regime-probabilities i{width:100%;min-height:4px;border-radius:4px 4px 1px 1px;background:linear-gradient(180deg,rgba(85,224,255,.80),rgba(22,76,131,.24));box-shadow:inset 0 1px 0 rgba(220,255,255,.10)}.regime-probabilities .active i{background:linear-gradient(180deg,#74f5ff 0%,#42c9ff 38%,#2874ff 100%);box-shadow:0 0 14px rgba(74,216,255,.36),inset 0 1px 0 rgba(255,255,255,.28)}.regime-probabilities small{color:rgba(203,222,240,.48);font-size:6.5px;font-weight:900;text-align:center;letter-spacing:.03em}
.flow-chart,.execution-chart{height:82px;margin-top:15px;border:1px solid rgba(82,205,255,.075);border-radius:13px;overflow:hidden;background:linear-gradient(180deg,rgba(14,54,92,.20),rgba(2,9,19,.045));box-shadow:inset 0 1px 0 rgba(128,226,255,.025)}.flow-chart svg,.execution-chart svg{width:100%;height:100%;display:block}
.risk-scale{position:relative;display:grid;grid-template-columns:repeat(4,1fr);margin-top:18px;padding-top:14px}.risk-scale span{font-size:6.5px;font-weight:950;text-align:center;color:rgba(205,223,240,.52);letter-spacing:.04em}.risk-scale .elevated{color:var(--amber)}.risk-scale .critical{color:var(--red)}.risk-scale i{position:absolute;top:0;width:9px;height:9px;border-radius:50%;transform:translateX(-50%);background:var(--amber);box-shadow:0 0 14px rgba(255,201,104,.82)}.risk-meter>span{background:linear-gradient(90deg,#2a70ff 0%,#57dcff 52%,#a9e8d8 72%,#ffc968 100%)}
.card-foot{margin-top:16px;padding-top:12px;font-size:10px;color:rgba(205,224,242,.64)}.mini-status i{width:7px;height:7px}.mini-status.good{color:#62f5b2}.mini-status.delayed{color:#ffc968}
/* Restore visual weight of the bottom workspaces without changing their structure. */
.capability-card{border-color:rgba(73,190,244,.24);border-radius:17px;background:radial-gradient(circle at 10% 0%,rgba(70,205,255,.035),transparent 28%),linear-gradient(180deg,rgba(5,20,38,.90),rgba(2,9,19,.82));box-shadow:inset 0 1px 0 rgba(255,255,255,.025),0 8px 20px rgba(0,0,0,.10)}
.cap-head{padding:13px 16px;border-bottom-color:rgba(82,205,255,.10)}.cap-title{font-size:12px;gap:11px;letter-spacing:.11em}.cap-symbol{width:28px;height:28px}.cap-symbol svg{width:24px;height:24px;stroke:#42aaff}.cap-head>span:last-child{font-size:20px;color:#58e7ff}
.cap-items{padding:10px;gap:7px}.cap-items>div{grid-template-columns:36px minmax(0,1fr);gap:11px;padding:10px 12px;border-radius:12px;border-color:rgba(80,205,255,.09);background:rgba(4,13,25,.36)}.cap-items i{width:31px;height:31px;border-radius:9px;background:rgba(34,127,240,.11)}.cap-items i svg{width:19px;height:19px}.cap-items b{font-size:11px}.cap-items small{font-size:8.5px;color:rgba(205,223,240,.66)}
/* Restore the brighter secure-access treatment visible in the approved reference. */
.secure-label{color:rgba(98,240,255,.86);text-shadow:0 0 12px rgba(80,222,255,.20)}.enter-terminal{width:min(470px,84vw);min-height:54px;border:1px solid rgba(145,235,255,.72);border-radius:16px;background:linear-gradient(90deg,#2d6dff 0%,#4bd2ff 100%);font-size:13px;font-weight:950;box-shadow:0 0 30px rgba(68,205,255,.34),0 0 70px rgba(35,113,255,.19),inset 0 0 18px rgba(255,255,255,.10)}.enter-terminal:hover{filter:brightness(1.08);box-shadow:0 0 42px rgba(86,220,255,.46),0 0 88px rgba(32,116,255,.24),inset 0 0 22px rgba(255,255,255,.13)}
.core-panel{position:relative;min-width:0;min-height:0;display:grid;grid-template-rows:minmax(0,1fr) auto;align-items:center;justify-items:center;overflow:visible;background:transparent;border:0}.core-panel:before{content:"";position:absolute;inset:1% 2% 13%;pointer-events:none;background:radial-gradient(circle at 50% 42%,rgba(75,201,255,.06),transparent 45%),radial-gradient(circle at 50% 43%,transparent 0 48%,rgba(87,211,255,.045) 48.3% 48.6%,transparent 48.9%)}.core-glow{position:absolute;left:50%;top:39%;width:78%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,rgba(79,226,255,.10) 0%,rgba(40,111,255,.08) 35%,transparent 69%);filter:blur(11px);animation:coreGlow 4.8s ease-in-out infinite}.reactor-stage{position:relative;z-index:2;width:min(95%,690px);height:min(48vh,465px);min-height:390px;display:grid;place-items:center;transition:transform .18s ease-out}.reactor-art-shell{position:relative;width:100%;height:100%;display:grid;place-items:center;overflow:visible}.reactor-art-shell:before{content:"";position:absolute;inset:10% 11% 8%;border-radius:50%;background:radial-gradient(circle,rgba(69,208,255,.10),rgba(29,96,198,.05) 40%,transparent 70%);filter:blur(10px);animation:reactorBlend 5.2s ease-in-out infinite}.reactor-art{position:relative;z-index:2;display:block;width:100%;height:100%;object-fit:contain;opacity:.96;filter:drop-shadow(0 18px 24px rgba(0,0,0,.25)) drop-shadow(0 0 20px rgba(76,210,255,.10)) saturate(1.02) brightness(.98);animation:reactorBreath 4.4s ease-in-out infinite}.reactor-energy-overlay{position:absolute;z-index:3;left:50%;top:48%;width:89%;aspect-ratio:1;transform:translate(-50%,-50%);overflow:visible;pointer-events:none;mix-blend-mode:screen}.overlay-rotor{transform-box:view-box;transform-origin:center}.overlay-rotor-a{animation:overlaySpin 34s linear infinite}.overlay-rotor-b{animation:overlaySpinReverse 8.2s linear infinite}.overlay-pulse{transform-box:view-box;transform-origin:center;animation:overlayCorePulse 2.4s ease-in-out infinite}.overlay-trace{stroke-dasharray:520;stroke-dashoffset:520;animation:overlayTrace 3.25s ease-in-out infinite}.overlay-trace.trace-b{animation-delay:.72s}.reactor-scan{position:absolute;z-index:4;left:50%;top:47%;width:56%;height:1px;transform:translate(-50%,-50%) rotate(-8deg);background:linear-gradient(90deg,transparent,rgba(225,255,255,.68),rgba(82,226,255,.25),transparent);box-shadow:0 0 11px rgba(82,226,255,.28);opacity:.18;animation:scanSweep 5.1s ease-in-out infinite}
.market-state-live{position:relative;z-index:6;width:min(64%,440px);margin-top:-38px;text-align:center;padding:0 8px 2px;background:transparent}.state-kicker{color:rgba(218,237,250,.76);font-size:10px;font-weight:900;letter-spacing:.22em}.state-title{margin-top:3px;color:#4ca7ff;font-size:24px;line-height:1;font-weight:950;letter-spacing:.16em;text-shadow:0 0 14px rgba(81,193,255,.18);animation:stateText 2.9s ease-in-out infinite}.state-confidence{margin-top:5px;color:#d9f1ff;font-size:12px;font-weight:780}.state-meter{position:relative;width:74%;height:5px;margin:9px auto 0;border-radius:99px;background:rgba(121,167,219,.17);overflow:visible}.state-meter span{display:block;width:78%;height:100%;border-radius:inherit;background:linear-gradient(90deg,#2c70ff,#75efff);box-shadow:0 0 14px rgba(84,224,255,.25);transform-origin:left center;animation:stateMeter 2.7s ease-in-out infinite}.state-meter i{position:absolute;left:78%;top:50%;width:8px;height:8px;border-radius:50%;transform:translate(-50%,-50%);background:#f6ffff;box-shadow:0 0 11px rgba(116,240,255,.64);animation:stateNode 2.7s ease-in-out infinite}.state-grid{width:72%;margin:10px auto 0;display:grid;grid-template-columns:repeat(3,1fr);gap:0}.state-grid>div{border-left:1px solid rgba(90,177,255,.13);text-align:center}.state-grid>div:first-child{border-left:0}.state-grid small{display:block;color:#4fdcff;font-size:8px;font-weight:950;letter-spacing:.15em}.state-grid strong{display:block;margin-top:2px;font-size:11px;font-weight:950}.state-grid em{display:block;margin-top:2px;color:rgba(222,239,251,.72);font-size:8px;font-weight:820;font-style:normal}
@keyframes coreGlow{0%,100%{opacity:.54;transform:translate(-50%,-50%) scale(.985)}50%{opacity:.95;transform:translate(-50%,-50%) scale(1.015)}}@keyframes reactorBlend{0%,100%{opacity:.55;transform:scale(.985)}50%{opacity:.92;transform:scale(1.015)}}@keyframes reactorBreath{0%,100%{filter:drop-shadow(0 18px 24px rgba(0,0,0,.25)) drop-shadow(0 0 17px rgba(76,210,255,.08)) saturate(1.00) brightness(.97)}50%{filter:drop-shadow(0 20px 28px rgba(0,0,0,.29)) drop-shadow(0 0 29px rgba(76,210,255,.16)) saturate(1.07) brightness(1.01)}}@keyframes overlaySpin{to{transform:rotate(360deg)}}@keyframes overlaySpinReverse{from{transform:rotate(360deg)}to{transform:rotate(0)}}@keyframes overlayCorePulse{0%,100%{opacity:.32;transform:scale(.96)}50%{opacity:.76;transform:scale(1.08)}}@keyframes overlayTrace{0%{stroke-dashoffset:520;opacity:.05}25%{opacity:.7}67%{stroke-dashoffset:0;opacity:.56}100%{stroke-dashoffset:-520;opacity:.05}}@keyframes scanSweep{0%,100%{opacity:.06;transform:translate(-50%,-50%) rotate(-13deg) scaleX(.72)}50%{opacity:.34;transform:translate(-50%,-50%) rotate(8deg) scaleX(1.08)}}@keyframes stateText{0%,100%{opacity:.90;text-shadow:0 0 5px rgba(76,167,255,.08)}50%{opacity:1;text-shadow:0 0 17px rgba(89,216,255,.28)}}@keyframes stateMeter{0%,100%{transform:scaleX(.985)}50%{transform:scaleX(1)}}@keyframes stateNode{0%,100%{left:76.8%;opacity:.72}50%{left:78.4%;opacity:1}}
.capability-grid{min-width:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.capability-card{min-width:0;overflow:hidden;border:1px solid rgba(73,190,244,.18);border-radius:14px;background:linear-gradient(180deg,rgba(5,19,36,.84),rgba(2,9,19,.76));box-shadow:inset 0 1px 0 rgba(255,255,255,.02)}.cap-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 13px;border-bottom:1px solid rgba(82,205,255,.07);background:linear-gradient(180deg,rgba(255,255,255,.014),transparent)}.cap-title{display:flex;align-items:center;gap:9px;color:#f1f7ff;font-size:11px;font-weight:950;letter-spacing:.10em}.cap-symbol{width:24px;height:24px;color:#47aaff;display:grid;place-items:center}.cap-symbol svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.cap-head>span:last-child{color:#5bddff;font-size:18px}.cap-items{padding:7px;display:grid;gap:5px}.cap-items>div{min-width:0;display:grid;grid-template-columns:31px minmax(0,1fr);align-items:center;gap:10px;padding:7px 9px;border:1px solid rgba(80,205,255,.075);border-radius:10px;background:rgba(4,13,25,.29);transition:border-color .15s ease,background .15s ease,transform .15s ease}.cap-items>div:hover{transform:translateY(-1px);border-color:rgba(84,215,255,.21);background:rgba(7,23,40,.43)}.cap-items i{width:27px;height:27px;display:grid;place-items:center;border-radius:8px;color:#41aaff;background:rgba(34,127,240,.08);font-style:normal}.cap-items i svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.cap-items b{display:block;color:#f2f7ff;font-size:10px}.cap-items small{display:block;margin-top:1px;color:rgba(205,223,240,.61);font-size:8px;line-height:1.18;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.entry-zone{display:grid;place-items:center;padding-bottom:1px}.secure-label{color:rgba(98,240,255,.76);font-size:8px;font-weight:950;letter-spacing:.25em}.lock{margin-right:4px;color:#7fb9ff}.enter-terminal{margin-top:6px;width:min(470px,84vw);min-height:54px;border:1px solid rgba(83,169,255,.64);border-radius:13px;background:linear-gradient(180deg,rgba(31,86,184,.42),rgba(10,38,86,.58));color:white;font:inherit;font-size:14px;font-weight:850;letter-spacing:.16em;cursor:pointer;box-shadow:0 0 22px rgba(53,160,255,.18),inset 0 1px 0 rgba(192,247,255,.13),inset 0 0 22px rgba(32,107,225,.12);transition:transform .15s ease,filter .15s ease,box-shadow .15s ease}.enter-terminal:hover{transform:translateY(-1px);filter:brightness(1.10);box-shadow:0 0 34px rgba(75,203,255,.27),inset 0 1px 0 rgba(225,255,255,.18)}.enter-terminal:active{transform:translateY(1px) scale(.998)}.enter-terminal[disabled]{cursor:wait;opacity:.88}.entry-meta{margin-top:7px;color:rgba(205,224,242,.45);font-size:8px;font-weight:750}.entry-meta i{margin:0 6px;color:rgba(88,205,255,.52);font-style:normal}.entry-feedback{min-height:7px;margin-top:2px;color:var(--cyan);font-size:7px;font-weight:850;letter-spacing:.10em}
@media(min-width:1200px) and (max-height:1080px){.jarvis{padding:8px 10px 7px;gap:7px}.topbar{padding:9px 13px}.brand-emblem{width:56px}.brand-copy h1{font-size:clamp(22px,1.5vw,29px)}.brand-kicker{font-size:10px}.brand-sub{margin-top:5px;font-size:9px}.clock-time{font-size:18px}.market-tape{min-height:34px}.tape-cell{padding:5px 6px}.hero-grid{gap:10px}.intel-stack{gap:10px}.intel-card{padding:12px 15px 10px 18px}.card-head h2{font-size:12px}.metric-rows{gap:6px;margin-top:8px}.metric-rows.spacious{gap:8px;margin-top:11px}.metric-rows span,.metric-rows b{font-size:10px}.regime-line{margin-top:8px}.regime-line>strong{font-size:16px}.card-foot{margin-top:10px;padding-top:7px;font-size:8px}.reactor-stage{width:min(94%,620px);height:min(45vh,410px);min-height:340px}.market-state-live{margin-top:-34px}.state-title{font-size:21px}.state-grid{margin-top:7px}.cap-head{padding:8px 10px}.cap-title{font-size:10px}.cap-symbol{width:21px;height:21px}.cap-items{padding:5px;gap:4px}.cap-items>div{grid-template-columns:27px 1fr;gap:8px;padding:5px 7px}.cap-items i{width:23px;height:23px}.cap-items b{font-size:9.5px}.cap-items small{font-size:7.5px}.enter-terminal{min-height:46px;width:min(420px,82vw);font-size:12px}.entry-meta{font-size:7px}}
@media(min-width:1200px) and (max-height:1080px){
.intel-card{padding:13px 16px 11px 19px}.card-head h2{font-size:12px}.regime-title{margin-top:9px}.regime-title strong{font-size:18px}.regime-title small{font-size:7.5px}.metric-rows,.metric-rows.compact-rows{gap:6px;margin-top:8px}.metric-rows span,.metric-rows b{font-size:10px}.meter{height:5px;margin-top:9px}.regime-probabilities{height:49px;margin-top:9px;padding:5px 7px 1px}.regime-probabilities small{font-size:5.3px}.flow-chart,.execution-chart{height:55px;margin-top:9px}.risk-scale{margin-top:10px;padding-top:9px}.risk-scale span{font-size:5.2px}.risk-scale i{width:7px;height:7px}.card-foot{margin-top:9px;padding-top:7px;font-size:8px}.cap-head{padding:9px 11px}.cap-title{font-size:10px}.cap-symbol{width:22px;height:22px}.cap-symbol svg{width:20px;height:20px}.cap-items{padding:6px;gap:4px}.cap-items>div{grid-template-columns:28px 1fr;gap:8px;padding:6px 8px}.cap-items i{width:24px;height:24px}.cap-items b{font-size:9.5px}.cap-items small{font-size:7px}.enter-terminal{min-height:46px;width:min(420px,82vw);font-size:12px}
}
@media(max-width:1500px){.topbar{grid-template-columns:minmax(0,1.12fr) minmax(400px,.88fr)}.hero-grid{grid-template-columns:minmax(255px,.80fr) minmax(490px,1.22fr) minmax(255px,.80fr)}.market-tape{grid-template-columns:repeat(6,1fr)}.tape-cell:nth-child(n+7){display:none}.reactor-stage{width:min(95%,610px)}}
@media(max-width:1150px){.jarvis{min-height:auto;overflow:visible;grid-template-rows:auto}.topbar{grid-template-columns:1fr}.system-block{grid-template-columns:170px 1fr}.hero-grid{grid-template-columns:1fr 1fr;grid-template-areas:"core core" "left right"}.core-panel{grid-area:core;min-height:510px}.left-stack{grid-area:left}.right-stack{grid-area:right}.capability-grid{grid-template-columns:repeat(2,1fr)}.reactor-stage{width:min(76vw,640px);height:430px}.brand-copy h1{white-space:normal}}
@media(max-width:760px){.jarvis{padding:7px;border-radius:14px}.brand-sub{display:none}.system-block{grid-template-columns:1fr}.clock-block{border-right:0;padding-right:0;padding-bottom:7px;border-bottom:1px solid rgba(91,212,255,.10)}.system-status{grid-template-columns:repeat(2,1fr)}.market-tape{grid-template-columns:repeat(3,1fr)}.tape-cell:nth-child(n+4){display:none}.hero-grid{grid-template-columns:1fr;grid-template-areas:"core" "left" "right"}.core-panel{min-height:470px}.reactor-stage{width:min(96vw,600px);height:360px;min-height:320px}.market-state-live{width:min(82%,380px);margin-top:-28px}.state-title{font-size:18px}.state-grid{width:88%}.intel-stack{grid-template-rows:auto auto}.capability-grid{grid-template-columns:1fr}.entry-zone{padding:3px 0 6px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.001ms!important;animation-iteration-count:1!important}}
"""

_COMPONENT_JS = r"""
export default function(component) {
    const { parentElement, setTriggerValue } = component;
    const root = parentElement.querySelector('#jarvis-root');
    const button = parentElement.querySelector('#jarvis-enter');
    const feedback = parentElement.querySelector('#jarvis-feedback');
    const stage = parentElement.querySelector('#reactor-stage');
    const canvas = parentElement.querySelector('#jarvis-particles');
    const ctx = canvas ? canvas.getContext('2d') : null;

    let animationFrame = null;
    let particles = [];
    let width = 0;
    let height = 0;
    let dpr = 1;
    let pointerX = .5;
    let pointerY = .5;
    let pointerActive = false;

    const updateClock = () => {
        const now = new Date();
        const dateNode = parentElement.querySelector('#jarvis-date');
        const timeNode = parentElement.querySelector('#jarvis-time');
        const tzNode = parentElement.querySelector('#jarvis-tz');
        const sessionNode = parentElement.querySelector('#jarvis-session');

        if (dateNode) {
            dateNode.textContent = new Intl.DateTimeFormat('fr-FR', {
                weekday: 'short', day: '2-digit', month: 'short', year: 'numeric'
            }).format(now);
        }
        if (timeNode) {
            timeNode.textContent = new Intl.DateTimeFormat('fr-FR', {
                hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
            }).format(now);
        }
        if (tzNode) {
            const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'LOCAL';
            tzNode.textContent = tz.split('/').pop().replaceAll('_', ' ').toUpperCase();
        }
        if (sessionNode) {
            const h = now.getHours();
            sessionNode.textContent = (h >= 7 && h < 22) ? 'SESSION ACTIVE' : 'OFF-HOURS SESSION';
        }
    };

    const resizeParticles = () => {
        if (!root || !canvas || !ctx) return;
        const rect = root.getBoundingClientRect();
        width = Math.max(1, rect.width);
        height = Math.max(1, rect.height);
        dpr = Math.min(window.devicePixelRatio || 1, 2);
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

        const count = width < 760 ? 16 : width < 1200 ? 24 : 36;
        particles = Array.from({length: count}, () => ({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - .5) * .14,
            vy: (Math.random() - .5) * .11,
            r: .6 + Math.random() * 1.35,
            a: .07 + Math.random() * .17,
        }));
    };

    const drawParticles = () => {
        if (!ctx) return;
        ctx.clearRect(0, 0, width, height);
        for (const p of particles) {
            if (pointerActive) {
                p.x += (pointerX * width - p.x) * .000012;
                p.y += (pointerY * height - p.y) * .000012;
            }
            p.x += p.vx;
            p.y += p.vy;
            if (p.x < -12) p.x = width + 12;
            if (p.x > width + 12) p.x = -12;
            if (p.y < -12) p.y = height + 12;
            if (p.y > height + 12) p.y = -12;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(86,230,255,${p.a})`;
            ctx.fill();
        }
        animationFrame = requestAnimationFrame(drawParticles);
    };

    const onPointerMove = (event) => {
        if (!root) return;
        const rect = root.getBoundingClientRect();
        pointerX = (event.clientX - rect.left) / rect.width;
        pointerY = (event.clientY - rect.top) / rect.height;
        pointerActive = true;
        if (stage) {
            const dx = (pointerX - .5) * 6;
            const dy = (pointerY - .5) * 5;
            stage.style.transform = `translate(${dx}px, ${dy}px)`;
        }
    };

    const onPointerLeave = () => {
        pointerActive = false;
        if (stage) stage.style.transform = 'translate(0px, 0px)';
    };

    const onEnter = () => {
        if (!button) return;
        button.disabled = true;
        button.innerHTML = 'INITIALIZING…';
        if (feedback) feedback.textContent = 'SECURE BRIDGE → PYTHON';
        setTriggerValue('enter', Date.now());
    };

    if (button) button.addEventListener('click', onEnter);
    if (root) {
        root.addEventListener('mousemove', onPointerMove);
        root.addEventListener('mouseleave', onPointerLeave);
    }

    const resizeObserver = new ResizeObserver(resizeParticles);
    if (root) resizeObserver.observe(root);

    resizeParticles();
    drawParticles();
    updateClock();
    const clockTimer = window.setInterval(updateClock, 1000);

    return () => {
        if (button) button.removeEventListener('click', onEnter);
        if (root) {
            root.removeEventListener('mousemove', onPointerMove);
            root.removeEventListener('mouseleave', onPointerLeave);
        }
        resizeObserver.disconnect();
        window.clearInterval(clockTimer);
        if (animationFrame) cancelAnimationFrame(animationFrame);
    };
}
"""


_jarvis_landing_component = st.components.v2.component(
    "jarvis_landing_v7_final_institutional",
    html=_COMPONENT_HTML,
    css=_COMPONENT_CSS,
    js=_COMPONENT_JS,
    isolate_styles=True,
)


def _enter_terminal() -> None:
    st.session_state["terminal_entered"] = True


def render_landing_page() -> None:
    """Render the final frameless JARVIS landing and enter the existing terminal via the V2 trigger."""
    st.markdown(
        """
        <style>
        [data-testid="stSidebar"] { display: none !important; }
        [data-testid="stHeader"] { display: none !important; }
        [data-testid="stToolbar"] { display: none !important; }
        [data-testid="stDecoration"] { display: none !important; }
        [data-testid="stStatusWidget"] { display: none !important; }
        #MainMenu { visibility: hidden !important; }
        footer { visibility: hidden !important; }
        html, body, [data-testid="stAppViewContainer"], [data-testid="stMain"] { background: #01050d !important; }
        .block-container { max-width: 100% !important; width: 100% !important; padding: 0 !important; margin: 0 !important; }
        </style>
        """,
        unsafe_allow_html=True,
    )
    _jarvis_landing_component(
        key="jarvis_landing_v7_final_institutional_instance",
        on_enter_change=_enter_terminal,
    )
